# DATA — live from Yahoo Finance, with a labelled sample fallback
# ════════════════════════════════════════════════════════════════
def _clean(df):
    """Make Yahoo data safe to use: single-level columns, no blank price rows."""
    if df is None or df.empty:
        return pd.DataFrame()
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = df.columns.get_level_values(0)
    df = df.loc[:, ~df.columns.duplicated()]
    keep = [c for c in ("Open", "High", "Low", "Close", "Volume") if c in df.columns]
    df = df[keep].apply(pd.to_numeric, errors="coerce")
    df = df.dropna(subset=["Open", "High", "Low", "Close"])   # Yahoo often sends today's row blank
    df = df[df["Close"] > 0]
    return df


def _sample_data(ticker, period, interval):
    """Realistic random-walk OHLC used ONLY when Yahoo Finance can't be reached."""
    seed = zlib.crc32(f"{ticker}{interval}".encode())
    rng = np.random.default_rng(seed)
    days = {"3mo": 63, "6mo": 126, "1y": 250}[period]
    base = {"^NSEI": 24800}.get(ticker, 400 + seed % 1500)
    if interval == "1h":
        idx = []
        d = datetime.now().replace(hour=9, minute=15, second=0, microsecond=0)
        while len(idx) < days * 7:
            if d.weekday() < 5:
                for h in range(7):
                    idx.append(d + timedelta(hours=h))
            d -= timedelta(days=1)
        idx = sorted(idx)[-days * 7:]
        vol = 0.0025
    else:
        idx = pd.bdate_range(end=datetime.now().date(), periods=days)
        vol = 0.011
    n = len(idx)
    drift = np.sin(np.linspace(0, 3 * np.pi, n)) * vol * 0.15
    close = np.exp(np.cumsum(rng.normal(0, vol, n) + drift))
    close = base * close / close[-1]
    open_ = np.concatenate([[close[0]], close[:-1]]) * (1 + rng.normal(0, vol / 3, n))
    high = np.maximum(open_, close) * (1 + abs(rng.normal(0, vol / 2, n)))
    low = np.minimum(open_, close) * (1 - abs(rng.normal(0, vol / 2, n)))
    return pd.DataFrame({"Open": open_, "High": high, "Low": low, "Close": close,
                         "Volume": rng.integers(1e5, 1e6, n)}, index=pd.DatetimeIndex(idx))


def fetch(ticker, period, interval):
    """Return (dataframe, is_live). Cached for CACHE_SECONDS."""
    key = (ticker, period, interval)
    hit = _cache.get(key)
    if hit and time.time() - hit[0] < CACHE_SECONDS:
        return hit[1], hit[2]
    try:
        with yf_lock:
            raw = yf.Ticker(ticker).history(period=period, interval=interval, auto_adjust=False)
        df = _clean(raw)
        if len(df) < 30:
            raise ValueError(f"only {len(df)} rows")
        live = True
    except Exception as e:
        print(f"[data] {ticker} {interval} unavailable ({e}) — using sample data")
        df, live = _sample_data(ticker, period, interval), False
    _cache[key] = (time.time(), df, live)
    return df, live


def fetch_info(ticker):
    key = ("info", ticker)
    hit = _cache.get(key)
    if hit and time.time() - hit[0] < 1800:
        return hit[1]
    try:
        info = yf.Ticker(ticker).info or {}
    except Exception:
        info = {}
    _cache[key] = (time.time(), info)
    return info


def last_price(ticker):
    if ticker == "^NSEI":
        df, _ = fetch("^NSEI", "6mo", "1h")
    else:
        df, _ = fetch(ticker, "1y", "1d")
    return r2(df["Close"].iloc[-1])


# ════════════════════════════════════════════════════════════════
# INDICATORS
# ════════════════════════════════════════════════════════════════
def rsi(close, n=14):
    delta = close.diff()
    gain = delta.clip(lower=0).ewm(alpha=1 / n, min_periods=n, adjust=False).mean()
    loss = (-delta.clip(upper=0)).ewm(alpha=1 / n, min_periods=n, adjust=False).mean()
    rs = gain / loss.replace(0, np.nan)
    return (100 - 100 / (1 + rs)).fillna(50)


def adx(df, n=14):
    high, low, close = df["High"], df["Low"], df["Close"]
    up, down = high.diff(), -low.diff()
    plus_dm = pd.Series(np.where((up > down) & (up > 0), up, 0.0), index=df.index)
    minus_dm = pd.Series(np.where((down > up) & (down > 0), down, 0.0), index=df.index)
    tr = pd.concat([high - low, (high - close.shift()).abs(),
                    (low - close.shift()).abs()], axis=1).max(axis=1)
    atr = tr.ewm(alpha=1 / n, adjust=False).mean().replace(0, np.nan)
    plus_di = 100 * plus_dm.ewm(alpha=1 / n, adjust=False).mean() / atr
    minus_di = 100 * minus_dm.ewm(alpha=1 / n, adjust=False).mean() / atr
    dx = 100 * (plus_di - minus_di).abs() / (plus_di + minus_di).replace(0, np.nan)
    return dx.ewm(alpha=1 / n, adjust=False).mean().fillna(0)


def candle_pattern(df):
    """Name the most recent candle pattern."""
    o, c, h, l = df["Open"].values, df["Close"].values, df["High"].values, df["Low"].values
    body = abs(c[-1] - o[-1])
    upper = h[-1] - max(c[-1], o[-1])
    lower = min(c[-1], o[-1]) - l[-1]
    green, red = c[-1] > o[-1], c[-1] < o[-1]
    prev_red, prev_green = c[-2] < o[-2], c[-2] > o[-2]
    if prev_red and green and c[-1] > o[-2] and o[-1] < c[-2]:
        return "Bullish engulfing", "bullish"
    if prev_green and red and c[-1] < o[-2] and o[-1] > c[-2]:
        return "Bearish engulfing", "bearish"
    if body > 0 and lower >= 2 * body and upper <= 0.3 * body:
        return "Hammer", "bullish"
    if body > 0 and upper >= 2 * body and lower <= 0.3 * body:
        return "Shooting star", "bearish"
    if green:
        return "Green candle", "bullish"
    if red:
        return "Red candle", "bearish"
    return "Doji (indecision)", "neutral"


def r2(x):
    try:
        x = float(x)
        return None if math.isnan(x) or math.isinf(x) else round(x, 2)
    except (TypeError, ValueError):
        return None


