# NIFTY 50 SIGNAL ENGINE  (B1 Spec 1 + Spec 2)
# ════════════════════════════════════════════════════════════════
def nifty_signal():
    df, live = fetch("^NSEI", "6mo", "1h")
    df = df.copy()
    c = df["Close"]
    df["MA20"], df["MA100"] = c.rolling(20).mean(), c.rolling(100).mean()
    df["MA400"] = c.rolling(400, min_periods=min(len(c), 200)).mean()
    df["RSI"], df["ADX"] = rsi(c), adx(df)
    last = df.iloc[-1]
    price, ma20, ma100, ma400 = r2(last["Close"]), r2(last["MA20"]), r2(last["MA100"]), r2(last["MA400"])
    rsi_v, adx_v = r2(last["RSI"]), r2(last["ADX"])
    # change vs previous trading day's close
    day_closes = c.groupby(df.index.date).last()
    prev_close = r2(day_closes.iloc[-2]) if len(day_closes) > 1 else price
    change = round(price - prev_close, 2)
    pattern, pattern_bias = candle_pattern(df)

    tail = df.iloc[-11:]
    crosses = int((tail["Close"] > tail["MA20"]).astype(int).diff().abs().sum())

    leaning_up = ma20 > ma100
    if leaning_up:
        rsi_ok = RSI_LONG[0] < rsi_v < RSI_LONG[1]
        trend_ok = price > ma400 and ma100 > ma400
        candle_ok = pattern_bias == "bullish"
        rsi_hi = RSI_LONG[1]
    else:
        rsi_ok = RSI_SHORT[0] < rsi_v < RSI_SHORT[1]
        trend_ok = price < ma400 and ma100 < ma400
        candle_ok = pattern_bias == "bearish"
        rsi_hi = RSI_SHORT[1]
    adx_ok = adx_v > ADX_MIN
    calm_ok = crosses <= 3
    word = "up" if leaning_up else "down"
    rng = RSI_LONG if leaning_up else RSI_SHORT

    conditions = [
        {"name": "Short-term direction", "ok": True,
         "status": f"The 20-hour average (₹{ma20:,.0f}) is {'above' if leaning_up else 'below'} the 100-hour average (₹{ma100:,.0f}), so recent prices are pointing {word}.",
         "learn": "A moving average smooths out noise. When the short average is above the long one, recent buyers are in control; below means sellers are."},
        {"name": "Big-picture trend agrees", "ok": trend_ok,
         "status": (f"Price and the 100-hour average are both {'above' if leaning_up else 'below'} the 400-hour average (₹{ma400:,.0f}) — the long-term trend agrees."
                    if trend_ok else f"The long-term 400-hour average (₹{ma400:,.0f}) does not confirm the {word}ward move yet."),
         "learn": "Trading with the long-term trend is safer than against it. Short moves that fight the big trend often fail."},
        {"name": "Momentum in a safe zone (RSI)", "ok": rsi_ok,
         "status": (f"RSI is {rsi_v} — inside the {rng[0]}–{rng[1]} range, so there is still room to move." if rsi_ok else
                    f"RSI is {rsi_v} — {'too high: the market may be overbought and due a pullback' if rsi_v >= rsi_hi else 'too low: the move may already be exhausted'}."),
         "learn": "RSI (0–100) measures how fast price has moved. Above 70 = overbought, below 30 = oversold. Entering in the middle avoids buying the top or selling the bottom."},
        {"name": "Trend is strong (ADX)", "ok": adx_ok,
         "status": (f"ADX is {adx_v} — above {ADX_MIN}, so this is a real trend." if adx_ok
                    else f"ADX is {adx_v} — below {ADX_MIN}, so the move is weak and could reverse easily."),
         "learn": "ADX measures trend strength, not direction. Weak trends (low ADX) give lots of false signals."},
        {"name": "Latest candle agrees", "ok": candle_ok,
         "status": f"The last hourly candle is a {pattern.lower()} — it {'supports' if candle_ok else 'does not support'} the {word}ward move.",
         "learn": "Each candle shows one hour of trading. Green = price closed higher than it opened; red = lower. Patterns like 'engulfing' show a shift in control."},
        {"name": "Market is not choppy", "ok": calm_ok,
         "status": (f"Price crossed its 20-hour average {crosses} time{'s' if crosses != 1 else ''} in the last 10 hours — calm enough to trust the signal." if calm_ok
                    else f"Price crossed its 20-hour average {crosses} times in the last 10 hours — the market is zig-zagging."),
         "learn": "In a choppy, sideways market, signals flip back and forth and lose money. This filter blocks trades until direction is clear."},
    ]
    met = sum(1 for x in conditions if x["ok"])
    key = ("BUY" if leaning_up else "SHORT") if met == len(conditions) else "HOLD"
    failed = [x["name"].split(" (")[0].lower() for x in conditions if not x["ok"]]
    explanation = {
        "BUY": "Every condition is met: prices are rising, the long-term trend agrees, momentum has room to run, the trend is strong and the market is calm. Historically this is a good time to consider buying.",
        "SHORT": "Every condition is met for a falling market: prices are dropping, the long-term trend agrees, momentum is bearish but not exhausted, and the trend is strong. This is when traders consider betting on a fall.",
        "HOLD": f"Not met: {', '.join(failed)}. When the picture is mixed, the safest action is to wait.",
    }[key]
    action = {
        "BUY": "Consider buying — practise it below with virtual money first.",
        "SHORT": "Consider staying out or selling — the market is likely to fall.",
        "HOLD": "Wait. No clear opportunity right now.",
    }[key]

    return {
        "key": key, "price": price, "change": change,
        "change_pct": round(change / prev_close * 100, 2) if prev_close else 0,
        "ma20": ma20, "ma100": ma100, "ma400": ma400, "rsi": rsi_v, "adx": adx_v,
        "conditions": conditions, "met": met, "total": len(conditions),
        "explanation": explanation, "action": action, "leaning": "up" if leaning_up else "down",
        "live": live, "updated": datetime.now().strftime("%d %b %Y, %H:%M"),
    }


def _dark(fig, height):
    fig.update_layout(
        height=height, margin=dict(l=8, r=8, t=8, b=8),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="#0d1117",
        font=dict(color="#c9d1d9", family="Inter, Arial, sans-serif", size=11),
        xaxis=dict(gridcolor="#21262d", rangeslider=dict(visible=False)),
        yaxis=dict(gridcolor="#21262d", side="right"),
        legend=dict(orientation="h", y=1.02, x=0, bgcolor="rgba(0,0,0,0)"),
        hovermode="x unified",
    )


def nifty_chart():
    """3-month daily candlestick with MA10 / MA50 overlays (B1 Spec 4)."""
    df, _ = fetch("^NSEI", "1y", "1d")
    df = df.copy()
    df["MA10"], df["MA50"] = df["Close"].rolling(10).mean(), df["Close"].rolling(50).mean()
    df = df.iloc[-63:]
    x = [d.strftime("%d %b") for d in df.index]
    fig = go.Figure([
        go.Candlestick(x=x, open=df["Open"], high=df["High"], low=df["Low"], close=df["Close"],
                       name="NIFTY 50", increasing_line_color="#3fb950", decreasing_line_color="#f85149"),
        go.Scatter(x=x, y=df["MA10"], name="10-day average", line=dict(color="#58a6ff", width=1.6)),
        go.Scatter(x=x, y=df["MA50"], name="50-day average", line=dict(color="#f0883e", width=1.6)),
    ])
    _dark(fig, 360)
    fig.update_xaxes(type="category", nticks=8)     # category axis = no weekend / holiday gaps
    return fig.to_json()


