# STOCK SCANNER
# ════════════════════════════════════════════════════════════════
def analyse_stock(ticker):
    df, live = fetch(ticker, "1y", "1d")
    df = df.copy()
    c = df["Close"]
    df["MA10"], df["MA50"] = c.rolling(10).mean(), c.rolling(50).mean()
    df["MA200"] = c.rolling(200).mean()
    df["RSI"], df["ADX"] = rsi(c), adx(df)
    last = df.iloc[-1]
    price = r2(last["Close"])
    ma10, ma50, ma200 = r2(last["MA10"]), r2(last["MA50"]), r2(last["MA200"])
    rsi_v, adx_v = r2(last["RSI"]) or 50, r2(last["ADX"]) or 0

    uptrend = ma10 > ma50 and (ma200 is None or price > ma200)
    downtrend = ma10 < ma50 and (ma200 is None or price < ma200)
    strong = adx_v > 25
    if uptrend and strong and RSI_LONG[0] < rsi_v < RSI_LONG[1]:
        key = "BUY"
    elif downtrend and strong and RSI_SHORT[0] < rsi_v < RSI_SHORT[1]:
        key = "SHORT"
    else:
        key = "HOLD"

    last3m = df.iloc[-63:]
    rets = np.log(last3m["Close"]).diff().dropna()
    mu, sd = float(rets.mean()), float(rets.std())

    def proj(n):
        mid = price * math.exp(mu * n)
        return {"mid": round(mid, 2), "pct": round((mid / price - 1) * 100, 1),
                "low": round(price * math.exp(mu * n - sd * math.sqrt(n)), 2),
                "high": round(price * math.exp(mu * n + sd * math.sqrt(n)), 2)}

    info = fetch_info(ticker)
    num = lambda k: info.get(k) if isinstance(info.get(k), (int, float)) else None
    pct = lambda k: r2(num(k) * 100) if num(k) is not None else None
    f = {
        "pe": r2(num("trailingPE")), "fpe": r2(num("forwardPE")),
        "eps": r2(num("trailingEps")), "pb": r2(num("priceToBook")),
        "roe": pct("returnOnEquity"), "de": r2(num("debtToEquity")),
        "rev_growth": pct("revenueGrowth"), "eps_growth": pct("earningsGrowth"),
        "div": r2(num("dividendYield")),
        "mcap_cr": r2(num("marketCap") / 1e7) if num("marketCap") else None,
        "target": r2(num("targetMeanPrice")),
        "rec": (info.get("recommendationKey") or "").replace("_", " ").upper() or None,
        "upside": None,
    }
    if f["target"]:
        f["upside"] = round((f["target"] / price - 1) * 100, 1)

    notes = ["Prices are in an uptrend (10-day average above 50-day)." if ma10 > ma50
             else "Prices are in a downtrend (10-day average below 50-day)."]
    if rsi_v > 70:
        notes.append(f"RSI {rsi_v:.0f} is high — the stock may be overbought.")
    elif rsi_v < 30:
        notes.append(f"RSI {rsi_v:.0f} is low — the stock may be oversold.")
    else:
        notes.append(f"RSI {rsi_v:.0f} is in a normal range.")
    notes.append(f"ADX {adx_v:.0f} — {'a strong trend' if strong else 'a weak trend, so signals are less reliable'}.")
    if f["pe"]:
        notes.append(f"P/E of {f['pe']:.0f}: investors pay ₹{f['pe']:.0f} for every ₹1 of yearly profit"
                     + (" — relatively expensive." if f["pe"] > 40 else " — moderate." if f["pe"] > 15 else " — relatively cheap."))
    if f["roe"] is not None:
        notes.append(f"ROE {f['roe']:.0f}% — ₹{f['roe']:.0f} profit for every ₹100 of shareholder money.")

    year = df.iloc[-250:]
    prev = r2(df["Close"].iloc[-2])
    return {
        "ticker": ticker, "name": STOCKS[ticker], "key": key, "price": price, "live": live, "error": False,
        "chg_pct": round((price / prev - 1) * 100, 2) if prev else 0,
        "ma10": ma10, "ma50": ma50, "ma200": ma200, "rsi": rsi_v, "adx": adx_v,
        "uptrend": ma10 > ma50, "strong": strong,
        "hi52": r2(year["High"].max()), "lo52": r2(year["Low"].min()),
        "support": r2(last3m["Low"].min()), "resistance": r2(last3m["High"].max()),
        "p3": proj(63), "p6": proj(126), "f": f, "notes": notes,
        "spark": [r2(v) for v in df["Close"].iloc[-126:]], "df": df,
    }


def safe_analyse(ticker):
    """One broken stock must never break the whole scanner page."""
    try:
        return analyse_stock(ticker)
    except Exception:
        print(f"[scanner] {ticker} failed:")
        traceback.print_exc()
        return {"ticker": ticker, "name": STOCKS[ticker], "error": True, "key": "HOLD", "live": False}


def scan_all():
    with ThreadPoolExecutor(max_workers=6) as pool:
        out = list(pool.map(safe_analyse, STOCKS))
    for s in out:
        s["group"] = "watch" if s["ticker"] in WATCHLIST else "popular"
    return out


def spark_json(values, key):
    values = [v for v in values if v is not None] or [0]
    color = {"BUY": "#3fb950", "SHORT": "#f85149"}.get(key, "#58a6ff")
    fill = {"BUY": "rgba(63,185,80,.08)", "SHORT": "rgba(248,81,73,.08)"}.get(key, "rgba(88,166,255,.08)")
    fig = go.Figure(go.Scatter(y=values, mode="lines", line=dict(color=color, width=2),
                               fill="tozeroy", fillcolor=fill, hoverinfo="skip"))
    lo, hi = min(values), max(values)
    fig.update_layout(height=64, margin=dict(l=0, r=0, t=0, b=0), showlegend=False,
                      paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      xaxis=dict(visible=False), yaxis=dict(visible=False, range=[lo * 0.98, hi * 1.02]))
    return fig.to_json()


def stock_chart(s):
    df = s["df"].iloc[-126:]
    last_date = df.index[-1]
    d3, d6 = last_date + timedelta(days=91), last_date + timedelta(days=182)
    fig = go.Figure([
        go.Candlestick(x=df.index, open=df["Open"], high=df["High"], low=df["Low"], close=df["Close"],
                       name="Price", increasing_line_color="#3fb950", decreasing_line_color="#f85149"),
        go.Scatter(x=df.index, y=df["MA50"], name="50-day average", line=dict(color="#f0883e", width=1.5)),
        go.Scatter(x=[last_date, d3, d6], y=[s["price"], s["p3"]["high"], s["p6"]["high"]],
                   mode="lines", line=dict(width=0), showlegend=False, hoverinfo="skip"),
        go.Scatter(x=[last_date, d3, d6], y=[s["price"], s["p3"]["low"], s["p6"]["low"]],
                   mode="lines", fill="tonexty", fillcolor="rgba(88,166,255,0.12)", line=dict(width=0),
                   name="Likely range", hoverinfo="skip"),
        go.Scatter(x=[last_date, d3, d6], y=[s["price"], s["p3"]["mid"], s["p6"]["mid"]],
                   name="Trend projection", mode="lines+markers",
                   line=dict(color="#58a6ff", width=2, dash="dash")),
    ])
    _dark(fig, 400)
    fig.update_xaxes(rangebreaks=[dict(bounds=["sat", "mon"])])
    return fig.to_json()


# ════════════════════════════════════════════════════════════════
# STORAGE
# ════════════════════════════════════════════════════════════════
class Store:
    """A tiny key → JSON store.  Online: Postgres (Neon).  On your computer: a SQLite file.
    One table, so the rest of the app just says  _load("algo")  /  _save("algo", data)."""

    def __init__(self, url):
        self.pg = url.startswith(("postgres://", "postgresql://"))
        self.url = url
        self.ph = "%s" if self.pg else "?"
        self.conn = None

    def _connect(self):
        if self.pg:
            import psycopg
            self.conn = psycopg.connect(self.url, autocommit=True, connect_timeout=20)
        else:
            self.conn = sqlite3.connect(os.path.join(DATA_DIR, "tradewise.db"),
                                        check_same_thread=False, isolation_level=None)
            self.conn.execute("PRAGMA journal_mode=WAL")
        self.conn.execute("CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL)")

    def _run(self, sql, args=(), fetch=False):
        sql = sql.replace("?", self.ph)
        with db_lock:
            for attempt in (1, 2):
                try:
                    if self.conn is None:
                        self._connect()
                    cur = self.conn.execute(sql, args)
                    return cur.fetchall() if fetch else None
                except Exception as e:
                    # Neon sleeps after 5 idle minutes and drops the connection — reconnect once
                    try:
                        self.conn.close()
                    except Exception:
                        pass
                    self.conn = None
                    if attempt == 2:
                        raise
                    print(f"[db] reconnecting ({type(e).__name__})")

    def get(self, k, default=None):
        rows = self._run("SELECT v FROM kv WHERE k = ?", (k,), fetch=True)
        return json.loads(rows[0][0]) if rows else default

    def put(self, k, v):
        self._run("INSERT INTO kv (k, v) VALUES (?, ?) ON CONFLICT (k) DO UPDATE SET v = excluded.v",
                  (k, json.dumps(v)))

    def delete(self, k):
        self._run("DELETE FROM kv WHERE k = ?", (k,))

    def with_prefix(self, prefix):
        rows = self._run("SELECT k, v FROM kv WHERE k LIKE ?", (prefix + "%",), fetch=True)
        return [(k, json.loads(v)) for k, v in rows]


db = Store(DATABASE_URL)
STATE, ALGO, SMTP_KEY = "state", "algo", "mail:smtp"


def _load(key, default):
    v = db.get(key)
    return v if v is not None else json.loads(json.dumps(default))


def _save(key, data):
    db.put(key, data)


def _import_old_files():
    """On your computer only: carry the old JSON files (before accounts existed) into the database."""
    if IS_CLOUD or db.get("meta:imported"):
        return

    def read(name):
        try:
            with open(os.path.join(DATA_DIR, name)) as f:
                return json.load(f)
        except Exception:
            return None
    for name, key in (("state.json", STATE), ("algo_account.json", ALGO), ("my_practice.json", "legacy:practice")):
        d = read(name)
        if d is not None and db.get(key) is None:
            db.put(key, d)
    old = read("settings.json") or {}
    if old.get("sender") and old.get("password"):
        db.put(SMTP_KEY, {"sender": old["sender"], "password": old["password"]})
    if old:
        db.put("legacy:settings", old)
    db.put("meta:imported", True)


def stamp():
    return datetime.now().strftime("%d %b %Y %H:%M")


# ── Accounts ────────────────────────────────────────────────────
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$")
users_lock = threading.Lock()


def get_user(uid):
    return db.get(f"user:{uid}") if uid else None


def find_user(email):
    uid = db.get(f"email:{(email or '').strip().lower()}")
    return get_user(uid)


def all_users():
    return [u for _, u in db.with_prefix("user:")]


def create_user(name, email, password):
    """Returns (user, error)."""
    name, email = (name or "").strip()[:40], (email or "").strip().lower()
    if not name:
        return None, "Please tell us your name."
    if not EMAIL_RE.match(email):
        return None, "That email address doesn’t look right."
    if len(password or "") < 8:
        return None, "Your password needs at least 8 characters."
    with users_lock:
        if db.get(f"email:{email}"):
            return None, "There’s already an account with this email — log in instead."
        first = not db.with_prefix("user:")
        uid = secrets.token_hex(8)
        user = {"id": uid, "name": name, "email": email, "created": stamp(),
                "hash": generate_password_hash(password)}
        db.put(f"user:{uid}", user)
        db.put(f"email:{email}", uid)
    if first and not IS_CLOUD:          # your own computer: the first account keeps your old trades
        old = db.get("legacy:practice")
        if old:
            db.put(practice_key(uid), old)
        old_set = db.get("legacy:settings") or {}
        if old_set:
            extra = [a.strip() for a in old_set.get("receiver", "").split(",") if a.strip() and a.strip().lower() != email]
            db.put(settings_key(uid), {**DEFAULT_SETTINGS, "extra": ", ".join(extra[:3]),
                                       "daily_summary": old_set.get("daily_summary", True),
                                       "signal_alerts": old_set.get("signal_alerts", False),
                                       "daily_time": old_set.get("daily_time", "15:45")})
    forget_schedule()
    return user, None


def set_password(user, password):
    user["hash"] = generate_password_hash(password)
    db.put(f"user:{user['id']}", user)


def delete_user(user):
    for k in (f"user:{user['id']}", f"email:{user['email']}", practice_key(user["id"]), settings_key(user["id"]), alerts_key(user["id"])):
        db.delete(k)
    forget_schedule()
    forget_price_alerts()


def is_admin(user):
    """Who may reset the shared algorithm account: the owner online, anyone on your own computer."""
    return bool(user) and (not IS_CLOUD or (bool(ADMIN_EMAIL) and user["email"] == ADMIN_EMAIL))


# ── Your own practice portfolio (one per account) ───────────────
def practice_key(uid):
    return f"practice:{uid}"


def new_practice():
    return {"cash": START_CAPITAL, "holdings": {}, "trades": []}


def practice_trade(uid, ticker, side, qty):
    """Returns (ok, message)."""
    if ticker not in TRADABLE:
        return False, "Unknown stock."
    if qty < 1:
        return False, "Enter a quantity of at least 1."
    if qty > 1_000_000:
        return False, "That quantity is too large."
    price = last_price(ticker)
    if not price:
        return False, "Price unavailable right now — try again in a minute."
    name = TRADABLE[ticker]
    with trade_lock:                    # two quick clicks can't spend the same cash twice
        p = _load(practice_key(uid), new_practice())
        h = p["holdings"].get(ticker, {"qty": 0, "avg": 0.0})
        if side == "BUY":
            cost = round(qty * price, 2)
            if cost > p["cash"] + 0.01:
                can = int(p["cash"] // price)
                return False, f"Not enough virtual cash: {qty} × ₹{price:,.2f} = ₹{cost:,.0f}, but you have ₹{p['cash']:,.0f}. You can afford {can}."
            h["avg"] = round((h["avg"] * h["qty"] + cost) / (h["qty"] + qty), 2)
            h["qty"] += qty
            p["cash"] = round(p["cash"] - cost, 2)
            p["holdings"][ticker] = h
            p["trades"].append({"time": stamp(), "ticker": ticker, "name": name, "side": "BUY",
                                "qty": qty, "price": price, "pnl": None})
            msg = f"Bought {qty} {name} at ₹{price:,.2f} (₹{cost:,.0f})."
        elif side == "SELL":
            if h["qty"] < qty:
                return False, f"You only own {h['qty']} {name}."
            pnl = round((price - h["avg"]) * qty, 2)
            p["cash"] = round(p["cash"] + qty * price, 2)
            h["qty"] -= qty
            if h["qty"] == 0:
                p["holdings"].pop(ticker, None)
            else:
                p["holdings"][ticker] = h
            p["trades"].append({"time": stamp(), "ticker": ticker, "name": name, "side": "SELL",
                                "qty": qty, "price": price, "pnl": pnl})
            msg = f"Sold {qty} {name} at ₹{price:,.2f} — {'profit' if pnl >= 0 else 'loss'} of ₹{abs(pnl):,.0f}."
        else:
            return False, "Choose Buy or Sell."
        p["trades"] = p["trades"][-1000:]
        _save(practice_key(uid), p)
    return True, msg


def practice_status(uid):
    p = _load(practice_key(uid), new_practice()) if uid else new_practice()
    rows, invested = [], 0.0
    for t, h in p["holdings"].items():
        price = last_price(t) or h["avg"]
        value = round(h["qty"] * price, 2)
        pnl = round((price - h["avg"]) * h["qty"], 2)
        invested += value
        rows.append({"ticker": t, "name": TRADABLE.get(t, t), "qty": h["qty"], "avg": h["avg"],
                     "price": price, "value": value, "pnl": pnl,
                     "pnl_pct": round((price / h["avg"] - 1) * 100, 2) if h["avg"] else 0})
    total = round(p["cash"] + invested, 2)
    sells = [t for t in p["trades"] if t["side"] == "SELL"]
    return {"cash": p["cash"], "invested": round(invested, 2), "total": total,
            "pnl": round(total - START_CAPITAL, 2), "ret": round((total / START_CAPITAL - 1) * 100, 2),
            "rows": sorted(rows, key=lambda r: -r["value"]),
            "holdings": {r["ticker"]: r for r in rows},
            "win_rate": round(sum(1 for t in sells if t["pnl"] > 0) / len(sells) * 100) if sells else None,
            "n_trades": len(p["trades"]), "trades": list(reversed(p["trades"]))[:50]}


# ── The algorithm's automatic account (shared by everyone) ──────
def new_algo():
    return {"cash": START_CAPITAL, "position": None, "trades": []}


def algo_status(price):
    p = _load(ALGO, new_algo())
    pos = p["position"]
    unreal = 0.0
    if pos:
        diff = price - pos["entry"] if pos["dir"] == "LONG" else pos["entry"] - price
        unreal = round(diff * pos["units"], 2)
    closed = [t for t in p["trades"] if t["type"] == "CLOSE"]
    wins = sum(1 for t in closed if t["pnl"] > 0)
    value = round(p["cash"] + unreal, 2)
    return {"value": value, "pnl": round(value - START_CAPITAL, 2),
            "ret": round((value / START_CAPITAL - 1) * 100, 2),
            "win_rate": round(wins / len(closed) * 100) if closed else None,
            "n_closed": len(closed), "position": pos, "unreal": unreal,
            "trades": list(reversed(p["trades"]))[:50]}


def algo_trade(signal, price):
    """Open on BUY/SHORT, close when the signal changes. Full capital per trade."""
    p = _load(ALGO, new_algo())
    pos = p["position"]
    want = {"BUY": "LONG", "SHORT": "SHORT"}.get(signal)
    if pos and pos["dir"] != want:
        diff = price - pos["entry"] if pos["dir"] == "LONG" else pos["entry"] - price
        pnl = round(diff * pos["units"], 2)
        p["cash"] = round(p["cash"] + pnl, 2)
        p["trades"].append({"time": stamp(), "type": "CLOSE", "dir": pos["dir"], "price": price, "pnl": pnl})
        p["position"] = pos = None
    if want and not pos:
        p["position"] = {"dir": want, "entry": price, "units": round(p["cash"] / price, 4), "time": stamp()}
        p["trades"].append({"time": stamp(), "type": "OPEN", "dir": want, "price": price, "pnl": None})
    _save(ALGO, p)


# ── Email ───────────────────────────────────────────────────────
def settings_key(uid):
    return f"settings:{uid}"


def get_settings(uid):
    return {**DEFAULT_SETTINGS, **(db.get(settings_key(uid)) or {})}


def recipients(user, st):
    extra = [a.strip() for a in st.get("extra", "").split(",") if EMAIL_RE.match(a.strip())]
    return [user["email"]] + [a for a in extra if a.lower() != user["email"]][:3]


def mail_config():
    """How TradeWise sends email. Set once by the site owner, never by visitors.
       Online:  BREVO_API_KEY + MAIL_FROM  (Render blocks normal email ports on free servers)
       Computer: a Gmail + App Password (env vars, or the owner box on the Settings page)"""
    if os.environ.get("BREVO_API_KEY") and os.environ.get("MAIL_FROM"):
        return {"kind": "brevo", "key": os.environ["BREVO_API_KEY"], "sender": os.environ["MAIL_FROM"]}
    sender, pw = os.environ.get("TRADEWISE_EMAIL_SENDER"), os.environ.get("TRADEWISE_EMAIL_PASSWORD")
    if not (sender and pw) and not IS_CLOUD:
        saved = db.get(SMTP_KEY) or {}
        sender, pw = saved.get("sender"), saved.get("password")
    if sender and pw:
        return {"kind": "smtp", "sender": sender, "password": pw}
    return None


def email_ready():
    return mail_config() is not None


def send_email(to, subject, text, html=None):
    """Returns (ok, message)."""
    cfg = mail_config()
    if not cfg:
        return False, "Email isn’t switched on for this TradeWise site yet."
    to = [a for a in to if a]
    try:
        if cfg["kind"] == "brevo":
            r = requests.post("https://api.brevo.com/v3/smtp/email", timeout=20,
                              headers={"api-key": cfg["key"], "accept": "application/json"},
                              json={"sender": {"name": "TradeWise", "email": cfg["sender"]},
                                    "to": [{"email": a} for a in to], "subject": subject,
                                    "textContent": text, **({"htmlContent": html} if html else {})})
            if r.status_code >= 300:
                return False, f"The email service said no ({r.status_code}): {r.text[:160]}"
        else:
            msg = MIMEMultipart("alternative")
            msg["Subject"], msg["From"], msg["To"] = subject, f"TradeWise <{cfg['sender']}>", ", ".join(to)
            msg.attach(MIMEText(text, "plain", "utf-8"))
            if html:
                msg.attach(MIMEText(html, "html", "utf-8"))
            with smtplib.SMTP("smtp.gmail.com", 587, timeout=20) as srv:
                srv.starttls()
                srv.login(cfg["sender"], cfg["password"].replace(" ", ""))
                srv.sendmail(cfg["sender"], to, msg.as_string())
        print(f"[email] sent: {subject} → {len(to)} recipient(s)")
        return True, f"Email sent to {', '.join(to)}."
    except smtplib.SMTPAuthenticationError:
        return False, "Gmail rejected the login. Use a 16-letter App Password, not your normal password."
    except Exception as e:
        return False, f"Couldn’t send email: {e}"


def send_alert(sig):
    if not email_ready():
        return
    for u in all_users():
        st = get_settings(u["id"])
        if st["signal_alerts"]:
            send_email(recipients(u, st), f"TradeWise: NIFTY 50 → {sig['key']}",
                       f"Hi {u['name']},\n\nThe TradeWise signal changed to {sig['key']}.\n\nNIFTY 50: ₹{sig['price']:,.2f}\n"
                       f"Time: {sig['updated']}\n\nWhy: {sig['explanation']}\n\nOpen TradeWise to see every condition."
                       + (f"\n{PUBLIC_URL}" if PUBLIC_URL else ""))


