AUTH_T = r"""{% extends "base" %}{% block title %}{{ heading }}{% endblock %}
{% block css %}
.auth{max-width:420px;margin:18px auto}
.auth h1{margin-bottom:4px}.auth .sub{color:var(--muted);margin-bottom:18px}
.field{display:grid;gap:5px;margin-bottom:14px}
.field label{font-weight:600;font-size:.9rem}
.field small{color:var(--muted);font-size:.8rem}
.inp{background:var(--bg);border:1px solid var(--line);color:var(--text);border-radius:9px;padding:11px 12px;font:inherit;width:100%}
.inp:focus{outline:2px solid var(--blue);outline-offset:-1px}
.err{background:var(--red-bg);border:1px solid #f8514966;color:#ffc1bb;border-radius:9px;padding:10px 12px;font-size:.9rem;margin-bottom:14px}
.note{background:var(--green-bg);border:1px solid #2ea04366;color:#aff5b4;border-radius:9px;padding:10px 12px;font-size:.9rem;margin-bottom:14px}
.auth .btn{width:100%;padding:12px}
.alt{text-align:center;margin-top:16px;font-size:.9rem;color:var(--muted)}
.perks{display:grid;gap:6px;margin:0 0 18px;font-size:.88rem;color:#c9d1d9;list-style:none}
.perks li::before{content:"✓ ";color:var(--green);font-weight:700}
.pw{position:relative}.pw button{position:absolute;right:8px;top:50%;transform:translateY(-50%);background:none;border:0;color:var(--muted);font:600 .78rem Inter,sans-serif;cursor:pointer;padding:4px 6px}
{% endblock %}
{% block body %}
<div class="auth card">
  <h1>{{ heading }}</h1><p class="sub">{{ sub }}</p>
  {% if error %}<div class="err" role="alert">{{ error }}</div>{% endif %}
  {% if note %}<div class="note" role="status">{{ note }}</div>{% endif %}
  {% if mode == 'signup' %}
  <ul class="perks"><li>₹1,00,000 of virtual money to practise with</li><li>Your own portfolio, saved on any device</li><li>Optional daily email about how you’re doing</li></ul>
  {% endif %}
  {% if mode != 'sent' %}
  <form method="post" novalidate>
    <input type="hidden" name="next" value="{{ next }}">
    {% if mode == 'signup' %}<div class="field"><label for="name">Your name</label><input class="inp" id="name" name="name" value="{{ form.name }}" maxlength="40" autocomplete="given-name" required></div>{% endif %}
    {% if mode in ('signup', 'login', 'forgot') %}<div class="field"><label for="email">Email</label><input class="inp" id="email" name="email" type="email" value="{{ form.email }}" autocomplete="email" inputmode="email" required></div>{% endif %}
    {% if mode in ('signup', 'login', 'reset') %}<div class="field"><label for="password">{{ 'New password' if mode == 'reset' else 'Password' }}</label>
      <div class="pw"><input class="inp" id="password" name="password" type="password" {{ 'minlength=8' if mode != 'login' }} autocomplete="{{ 'current-password' if mode == 'login' else 'new-password' }}" required><button type="button" onclick="var p=document.getElementById('password');p.type=p.type==='password'?'text':'password';this.textContent=p.type==='password'?'Show':'Hide'">Show</button></div>
      {% if mode != 'login' %}<small>At least 8 characters.</small>{% else %}<small><a href="/forgot">Forgot your password?</a></small>{% endif %}</div>{% endif %}
    <button class="btn">{{ button }}</button>
  </form>
  {% endif %}
  {% if mode == 'signup' %}<p class="alt">Already have an account? <a href="/login?next={{ next|urlencode }}">Log in</a></p>
  {% elif mode == 'login' %}<p class="alt">New to TradeWise? <a href="/signup?next={{ next|urlencode }}">Create a free account</a></p>
  {% else %}<p class="alt"><a href="/login">Back to log in</a></p>{% endif %}
</div>
{% endblock %}"""

OFFLINE_HTML = """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TradeWise · Offline</title><meta name="theme-color" content="#0d1117"></head>
<body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#0d1117;color:#e6edf3;font-family:-apple-system,Segoe UI,Arial,sans-serif;text-align:center;padding:24px">
<div><img src="/icon-192.png" width="72" height="72" style="border-radius:16px" alt=""><h1 style="font-size:1.4rem;margin:16px 0 6px">Can’t reach TradeWise</h1>
<p style="color:#8b949e;max-width:340px">You seem to be offline. Check your internet connection, then try again.</p>
<button onclick="location.reload()" style="margin-top:10px;background:#238636;color:#fff;border:0;border-radius:9px;padding:10px 20px;font-weight:600;font-size:15px">Try again</button></div></body></html>"""

SERVICE_WORKER = """const CACHE='tradewise-v2';
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/offline','/icon-192.png'])));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==CACHE).map(x=>caches.delete(x)))));self.clients.claim();});
self.addEventListener('fetch',e=>{
  const r=e.request;
  if(r.mode==='navigate'){ e.respondWith(fetch(r).catch(()=>caches.match('/offline'))); return; }
  if(r.url.endsWith('.png')){ e.respondWith(caches.match(r).then(h=>h||fetch(r))); }
});"""

ERROR_T = r"""{% extends "base" %}{% block title %}Oops{% endblock %}
{% block body %}<div class="card" style="text-align:center;padding:40px 20px;max-width:560px;margin:30px auto"><h1>Oops</h1><p class="muted" style="margin:8px 0 18px">{{ msg }}</p><a class="btn" href="/">Back to dashboard</a></div>{% endblock %}"""

TOPICS = [
    ("NIFTY 50", "An index that tracks the 50 biggest companies on India’s National Stock Exchange, such as Reliance, HDFC Bank and Infosys. When people say “the market went up”, they usually mean the NIFTY 50.",
     "If the NIFTY 50 moves from 24,000 to 24,240, the market rose 1%."),
    ("Technical vs fundamental", "Fundamental analysis studies the business — its profits, debt and growth — to decide what is worth buying. Technical analysis studies price charts to decide when to buy or sell. TradeWise shows both.",
     "A company with strong profits can still be a bad buy this week if its price is falling fast."),
    ("Moving average", "The average closing price over the last N periods. It smooths out daily noise so you can see the real direction. A short average above a long average means recent prices are higher — an uptrend.",
     "The 20-hour average is ₹24,300 and the 100-hour average is ₹24,100, so the short-term trend is up."),
    ("RSI", "Relative Strength Index — a score from 0 to 100 showing how fast price has moved recently. Above 70 means it rose very quickly and may pull back (overbought). Below 30 means it fell very quickly and may bounce (oversold).",
     "An RSI of 82 is a warning that buyers may be running out of steam."),
    ("ADX", "Average Directional Index — measures how strong a trend is, not which way it goes. Above about 25 the trend is real; below it, the market is drifting sideways and signals are unreliable.",
     "ADX of 35 in a rising market means the rise is strong. ADX of 12 means it’s mostly noise."),
    ("Candlesticks", "Each candle shows one period of trading. The thick body runs from the opening price to the closing price; the thin wicks show the highest and lowest prices. Green = closed higher, red = closed lower.",
     "A “bullish engulfing” is a big green candle that completely covers the red one before it — buyers took control."),
    ("Support & resistance", "Support is a price level where a stock has stopped falling before (buyers step in). Resistance is where it has stopped rising before (sellers step in).",
     "If a stock bounced off ₹1,400 three times, ₹1,400 is support."),
    ("P/E ratio", "Price divided by yearly profit per share — how many rupees investors pay for each rupee of profit. Higher can mean expensive, or that investors expect fast growth.",
     "A P/E of 25 means you pay ₹25 for every ₹1 the company earns in a year."),
    ("ROE", "Return on Equity — how much profit a company makes with its shareholders’ money. Above 15% is usually considered healthy.",
     "ROE of 18% means ₹18 of profit for every ₹100 shareholders have invested."),
    ("BUY, HOLD, SHORT", "BUY means conditions suggest prices may rise. SHORT means they suggest prices may fall — a short trade profits when prices drop. HOLD means the picture is unclear, so the safest choice is to wait.",
     "TradeWise only says BUY or SHORT when all six conditions agree."),
    ("Paper trading", "Practising with pretend money in real market conditions. Professional traders always paper-trade a strategy before risking real money. Use the Practice page to try it.",
     "Buy 2 units of NIFTY 50 with virtual cash today and watch your profit or loss change tomorrow."),
    ("Projections", "The projection lines on stock pages simply continue the recent average daily move. Markets react to news nobody can predict, so treat them as “if nothing changes” scenarios.",
     "A +8% 3-month projection means “if the last 3 months repeat”, not “this will happen”."),
]

