@app.context_processor
def nav_signal_ctx():
    """Small signal badge in the top bar — uses the last logged signal, never slows pages."""
    st = _load(STATE, {"history": []})
    h = st["history"][-1] if st.get("history") else None
    mine = get_alerts(g.user["id"])["items"] if getattr(g, "user", None) else []
    return {"nav_signal": {"key": h["signal"], "price": h["price"]} if h else None, "my_alerts": mine}


def _safe_next(url, fallback="/practice"):
    return url if isinstance(url, str) and url.startswith("/") and not url.startswith("//") and "\\" not in url else fallback


def _with_msg(url, msg, kind="ok"):
    path, _, frag = url.partition("#")
    sep = "&" if "?" in path else "?"
    return f"{path}{sep}msg={quote(msg)}&kind={kind}" + (f"#{frag}" if frag else "")


