def _secret_key():
    if os.environ.get("SECRET_KEY"):
        return os.environ["SECRET_KEY"]
    if IS_CLOUD:
        print("[warning] SECRET_KEY is not set — everyone will be logged out whenever the server restarts.")
        return secrets.token_hex(32)
    key = db.get("meta:secret")              # on your computer: make one once and keep it
    if not key:
        key = secrets.token_hex(32)
        db.put("meta:secret", key)
    return key


app.secret_key = _secret_key()
_import_old_files()
reset_tokens = URLSafeTimedSerializer(app.secret_key, salt="tradewise-password-reset")
_failed = {}                                  # ip → recent failed login times (slows down password guessing)
STATIC = (".png", ".js", ".webmanifest")


@app.before_request
def load_user_and_check():
    g.user = None
    if request.path.endswith(STATIC) or request.path.startswith("/cron/") or request.path == "/healthz":
        return
    g.user = get_user(session.get("uid"))
    if session.get("uid") and not g.user:
        session.clear()
    # Forms must come from TradeWise itself (stops other websites submitting trades for you)
    if request.method == "POST":
        origin = request.headers.get("Origin") or request.headers.get("Referer")
        if origin and origin != "null" and urlparse(origin).netloc != request.host:
            abort(403)


def login_required(view):
    @wraps(view)
    def wrapper(*a, **kw):
        if not g.user:
            nxt = request.form.get("next") if request.method == "POST" else request.full_path.rstrip("?")
            return redirect(url_for("login", next=_safe_next(nxt, "/practice")))
        return view(*a, **kw)
    return wrapper


def _too_many_attempts():
    ip, now = request.remote_addr or "?", time.time()
    _failed[ip] = [t for t in _failed.get(ip, []) if now - t < 900]
    return len(_failed[ip]) >= 10


def _log_in(user):
    session.clear()
    session["uid"] = user["id"]
    session.permanent = True


def _auth_page(mode, error=None, note=None, status=200, **kw):
    text = {
        "signup": ("Create your free account", "Start practising in under a minute.", "Create account"),
        "login": ("Welcome back", "Log in to see your practice portfolio.", "Log in"),
        "forgot": ("Reset your password", "We’ll email you a link to choose a new one.", "Send reset link"),
        "reset": ("Choose a new password", "Then you’ll be logged straight in.", "Save new password"),
        "sent": ("Check your email", "", ""),
    }[mode]
    nxt = _safe_next(request.values.get("next"), "/practice")
    return render_template("auth", active=mode, mode=mode, heading=text[0], sub=text[1], button=text[2],
                           error=error, note=note, next=nxt, form=request.form, **kw), status


@app.route("/signup", methods=["GET", "POST"])
def signup():
    if g.user:
        return redirect("/practice")
    if request.method == "POST":
        if _too_many_attempts():
            return _auth_page("signup", "Too many attempts — please wait 15 minutes.", status=429)
        user, err = create_user(request.form.get("name"), request.form.get("email"), request.form.get("password"))
        if err:
            return _auth_page("signup", err, status=400)
        _log_in(user)
        first = user["name"].split()[0]
        return redirect(_with_msg(_safe_next(request.form.get("next")), f"Welcome, {first}! You have ₹1,00,000 of virtual cash to practise with."))
    return _auth_page("signup")


@app.route("/login", methods=["GET", "POST"])
def login():
    if g.user:
        return redirect(_safe_next(request.args.get("next")))
    if request.method == "POST":
        if _too_many_attempts():
            return _auth_page("login", "Too many wrong passwords — please wait 15 minutes and try again.", status=429)
        user = find_user(request.form.get("email"))
        if not user or not check_password_hash(user["hash"], request.form.get("password", "")):
            _failed.setdefault(request.remote_addr or "?", []).append(time.time())
            return _auth_page("login", "That email and password don’t match.", status=401)
        _log_in(user)
        return redirect(_safe_next(request.form.get("next")))
    return _auth_page("login")


