@app.route("/forgot", methods=["GET", "POST"])
def forgot():
    if request.method == "POST":
        if not email_ready():
            return _auth_page("forgot", "Password reset by email isn’t switched on for this site yet — ask the site owner.")
        if _too_many_attempts():
            return _auth_page("forgot", "Too many attempts — please wait 15 minutes.", status=429)
        _failed.setdefault(request.remote_addr or "?", []).append(time.time())
        user = find_user(request.form.get("email"))
        if user:
            token = reset_tokens.dumps({"u": user["id"], "h": user["hash"][-12:]})
            link = (PUBLIC_URL or request.host_url.rstrip("/")) + url_for("reset_password", token=token)
            send_email([user["email"]], "Reset your TradeWise password",
                       f"Hi {user['name']},\n\nSomeone (hopefully you) asked to reset your TradeWise password.\n"
                       f"Open this link within 1 hour to choose a new one:\n\n{link}\n\n"
                       "If it wasn’t you, ignore this email — your password stays the same.")
        return _auth_page("sent", note="If an account exists for that email, a reset link is on its way. It works for 1 hour — check your spam folder too.")
    return _auth_page("forgot")


@app.route("/reset/<token>", methods=["GET", "POST"])
def reset_password(token):
    try:
        data = reset_tokens.loads(token, max_age=3600)
        user = get_user(data.get("u"))
        if not user or user["hash"][-12:] != data.get("h"):
            raise BadSignature("used")
    except SignatureExpired:
        return _auth_page("forgot", "That reset link has expired — ask for a new one.", status=400)
    except BadSignature:
        return _auth_page("forgot", "That reset link isn’t valid any more — ask for a new one.", status=400)
    if request.method == "POST":
        pw = request.form.get("password", "")
        if len(pw) < 8:
            return _auth_page("reset", "Your password needs at least 8 characters.", status=400)
        set_password(user, pw)
        _log_in(user)
        return redirect(_with_msg("/practice", "Password changed — you’re logged in."))
    return _auth_page("reset")


