@app.route("/cron/tick")
def cron_tick():
    """Hit every 10 minutes by cron-job.org: keeps the free server awake and runs anything due."""
    key = request.args.get("key", "") or request.headers.get("X-Cron-Key", "")
    if not CRON_SECRET or not hmac.compare_digest(key, CRON_SECRET):
        abort(403)
    if request.args.get("wait"):                          # ?wait=1 to see the result (for testing)
        return jsonify(tick())
    threading.Thread(target=tick, daemon=True).start()    # answer instantly so the pinger never times out
    return jsonify({"ok": True, "started": stamp()})


