SCHED = None


def start_scheduler():
    """On your computer: run the same tick() the online version gets from cron-job.org, every 5 minutes."""
    global SCHED
    from apscheduler.schedulers.background import BackgroundScheduler
    SCHED = BackgroundScheduler(timezone="Asia/Kolkata")
    SCHED.add_job(tick, "interval", minutes=5, next_run_time=datetime.now() + timedelta(seconds=20),
                  coalesce=True, max_instances=1, id="tick")
    SCHED.start()
    return SCHED


