# RUNNING AS AN APP
# ════════════════════════════════════════════════════════════════
def _port_busy():
    with socket.socket() as sk:
        sk.settimeout(0.5)
        return sk.connect_ex(("127.0.0.1", PORT)) == 0


def _serve_in_background():
    if _port_busy():          # TradeWise is already running (e.g. from Terminal) — just reuse it
        print("TradeWise is already running — opening it.")
        return
    start_scheduler()
    threading.Thread(target=lambda: app.run(host="0.0.0.0", port=PORT, debug=False,
                                            threaded=True, use_reloader=False), daemon=True).start()
    for _ in range(100):
        if _port_busy():
            break
        time.sleep(0.1)


def run_app_window():
    """Open TradeWise in its own native window (needs `pywebview`); falls back to the browser."""
    url = f"http://127.0.0.1:{PORT}"
    _serve_in_background()
    try:
        import webview
    except ImportError:
        print("pywebview not installed — opening in your browser instead.")
        webbrowser.open(url)
        while True:
            time.sleep(3600)
    if sys.platform == "darwin":          # show "TradeWise" + our icon in the Dock and menu bar
        try:
            from AppKit import NSApplication, NSImage
            from Foundation import NSBundle, NSData
            info = NSBundle.mainBundle().localizedInfoDictionary() or NSBundle.mainBundle().infoDictionary()
            info["CFBundleName"] = "TradeWise"
            raw = base64.b64decode(ICON_PNG["mac-1024.png"])
            img = NSImage.alloc().initWithData_(NSData.dataWithBytes_length_(raw, len(raw)))
            NSApplication.sharedApplication().setApplicationIconImage_(img)
        except Exception:
            pass
    webview.create_window("TradeWise", url, width=1280, height=860, min_size=(400, 640),
                          background_color="#0d1117", text_select=True)
    webview.start()


def install_mac_app():
    """Build TradeWise.app so it opens from Launchpad / the Dock like any other app."""
    if sys.platform != "darwin":
        print("The app installer is for macOS. On Windows/Linux run:  python tradewise.py --app")
        return
    py, script = sys.executable, os.path.abspath(__file__)
    print("1/3  Installing the native window library (pywebview)…")
    r = subprocess.run([py, "-m", "pip", "install", "--upgrade", "pywebview"])
    if r.returncode != 0:
        subprocess.run([py, "-m", "pip", "install", "--user", "--upgrade", "pywebview"])

    print("2/3  Building TradeWise.app…")
    target_dir = "/Applications" if os.access("/Applications", os.W_OK) else os.path.expanduser("~/Applications")
    os.makedirs(target_dir, exist_ok=True)
    app_path = os.path.join(target_dir, "TradeWise.app")
    subprocess.run(["rm", "-rf", app_path])
    macos, res = os.path.join(app_path, "Contents/MacOS"), os.path.join(app_path, "Contents/Resources")
    os.makedirs(macos)
    os.makedirs(res)
    launcher = os.path.join(macos, "TradeWise")
    with open(launcher, "w") as f:
        f.write(f'#!/bin/bash\ncd "{os.path.dirname(script)}"\nexec "{py}" "{script}" --app >> "{DATA_DIR}/app.log" 2>&1\n')
    os.chmod(launcher, 0o755)
    with open(os.path.join(app_path, "Contents/Info.plist"), "w") as f:
        f.write("""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
<key>CFBundleName</key><string>TradeWise</string>
<key>CFBundleDisplayName</key><string>TradeWise</string>
<key>CFBundleIdentifier</key><string>com.vihaanjain.tradewise</string>
<key>CFBundleVersion</key><string>1.0</string>
<key>CFBundleShortVersionString</key><string>1.0</string>
<key>CFBundlePackageType</key><string>APPL</string>
<key>CFBundleExecutable</key><string>TradeWise</string>
<key>CFBundleIconFile</key><string>TradeWise</string>
<key>LSMinimumSystemVersion</key><string>10.13</string>
<key>NSHighResolutionCapable</key><true/>
</dict></plist>""")
    # icon: PNG → .iconset → .icns using the tools built into macOS
    tmp = os.path.join(DATA_DIR, "TradeWise.iconset")
    subprocess.run(["rm", "-rf", tmp])
    os.makedirs(tmp)
    master = os.path.join(tmp, "master.png")
    with open(master, "wb") as f:
        f.write(base64.b64decode(ICON_PNG["mac-1024.png"]))
    for size in (16, 32, 128, 256, 512):
        for scale in (1, 2):
            px = size * scale
            name = f"icon_{size}x{size}{'@2x' if scale == 2 else ''}.png"
            subprocess.run(["sips", "-z", str(px), str(px), master, "--out", os.path.join(tmp, name)],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    os.remove(master)
    subprocess.run(["iconutil", "-c", "icns", tmp, "-o", os.path.join(res, "TradeWise.icns")])
    subprocess.run(["rm", "-rf", tmp])
    subprocess.run(["touch", app_path])

    print(f"3/3  Done!  TradeWise is in {target_dir}.")
    print("     Open it from Launchpad or Applications, then drag it to your Dock.")
    print("     (If macOS says it can't check the app: right-click TradeWise → Open → Open.)")
    subprocess.run(["open", "-R", app_path])


if __name__ == "__main__":
    args = sys.argv[1:]
    if "--install-mac-app" in args:
        install_mac_app()
    elif "--app" in args:
        run_app_window()
    else:
        if _port_busy():
            print(f"Port {PORT} is already in use — TradeWise may already be running. Opening it…")
            webbrowser.open(f"http://127.0.0.1:{PORT}")
            sys.exit(0)
        start_scheduler()
        print("\n  TradeWise is running →  http://127.0.0.1:%d" % PORT)
        print("  On your phone (same Wi-Fi) →  http://%s:%d" % (lan_ip(), PORT))
        print("  Hourly checks Mon–Fri 9:20–15:20 · Daily emails:",
              "ON" if email_ready() else "off (add a sending account in Settings)")
        print('  Want it as an app?  run:  %s "%s" --install-mac-app\n' % (sys.executable, os.path.abspath(__file__)))
        if "--no-browser" not in args:
            threading.Timer(1.2, lambda: webbrowser.open(f"http://127.0.0.1:{PORT}")).start()
        app.run(host="0.0.0.0", port=PORT, debug=False, threaded=True)
